import { useParams, useNavigate } from 'react-router-dom';
import { useEffect } from 'react';

const SUPPORTED_LANGUAGES = ['fr', 'ar', 'es'];
const DEFAULT_LANGUAGE = 'fr';

export const useLanguage = () => {
  const { lang } = useParams();
  const navigate = useNavigate();

  // Vérifier si la langue est supportée
  useEffect(() => {
    if (!SUPPORTED_LANGUAGES.includes(lang)) {
      navigate(`/${DEFAULT_LANGUAGE}${window.location.pathname}`);
    }
  }, [lang, navigate]);

  // Fonction pour changer la langue
  const setLanguage = (newLang) => {
    if (SUPPORTED_LANGUAGES.includes(newLang)) {
      const currentPath = window.location.pathname;
      const newPath = currentPath.replace(/^\/[a-z]{2}/, `/${newLang}`);
      navigate(newPath);
    }
  };

  // Obtenir la direction selon la langue
  const direction = lang === 'ar' ? 'rtl' : 'ltr';

  // Obtenir la police selon la langue
  const fontFamily = lang === 'ar' ? 'font-arabic' : 'font-default';

  return {
    lang,
    direction,
    fontFamily,
    isRTL: lang === 'ar',
    setLanguage
  };
}; 